// Synthetic replica of react-native-screens@4 sources: TSX shipped as the
// "react-native" entry, registering a native component off the React Native
// default export and rendering it as a host component.
import ReactNative from "react-native";

type ScreenProps = {
  active?: number;
  children?: unknown;
};

const ScreenNativeComponent =
  (ReactNative as { requireNativeComponent?: (name: string) => unknown }).requireNativeComponent?.(
    "RNSScreen",
  ) ?? "RNSScreen";

export const SCREENS_OK = "SCREENS_OK";

export function enableScreens(shouldEnableScreens = true): boolean {
  return shouldEnableScreens;
}

export function Screen(props: ScreenProps) {
  return <ScreenNativeComponent active={props.active ?? 1}>{props.children}</ScreenNativeComponent>;
}

export function ScreenContainer(props: ScreenProps) {
  return <Screen {...props} />;
}
